extracted_python_code:
filtered_customers = Customers.WHERE(
    (
        STARTSWITH(LOWER(name), "j") | ENDSWITH(LOWER(name), "ez")
    ) &
    ENDSWITH(LOWER(state), "a")
)
result = Broker.CALCULATE(
    num_matching_customers=COUNT(filtered_customers)
)

distinct_buying_customer_ids = Transactions.WHERE(transaction_type == 'buy').PARTITION(name="distinct_customers", by=customer_id).CALCULATE(
    customer_id=customer_id
)

transactions_from_recent_customers = Broker.CALCULATE(
    num_transactions_recent_joiners=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, 'now') <= 70
        ).transactions_made
    )
)

asp_q1_2023 = Dealership.CALCULATE(
    average_sale_price_q1_2023=AVG(
        Sales.WHERE(
            (YEAR(sale_date) == 2023) & 
            ISIN(MONTH(sale_date), (1, 2, 3))
        ).sale_price
    )
)

result = Dealership.CALCULATE(
    average_payment_lag_days=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                lag_in_days=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).lag_in_days
        ),
        2
    )
)

highest_priced_car_sold_on_inventory_out_day = Sales.WHERE(
    HAS(car.inventory_snapshots.WHERE((is_in_inventory == False) & (snapshot_date == sale_date))) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    car_make=car.make,
    car_model=car.model,
    sale_price=sale_price
)

tsc_past_7_days = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, DATETIME('now')) < 7))
)

distinct_customer_ids_with_purchases = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id = _id
)

distinct_salespersons_with_cash_payment = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == "cash")) == 1
).CALCULATE(
    salesperson_id=_id
)

# Define the start and end dates for the 3-month period
start_period_date = DATETIME('now', '-3 months')
end_period_date = DATETIME('now')

# Find the top 3 salespersons by revenue in the last 3 months
top_sales_reps_by_revenue = Salespersons.WHERE(
    HAS(sales_made.WHERE(
        (sale_date >= start_period_date) & (sale_date <= end_period_date)
    )) == 1  # Ensure the salesperson has sales in the specified period
).CALCULATE(
    rep_first_name=first_name,
    rep_last_name=last_name,
    total_sales_num=COUNT(
        sales_made.WHERE(
            (sale_date >= start_period_date) & (sale_date <= end_period_date)
        )
    ),
    total_revenue_val=SUM(
        sales_made.WHERE(
            (sale_date >= start_period_date) & (sale_date <= end_period_date)
        ).sale_price
    )
).TOP_K(3, by=total_revenue_val.DESC())

weekend_payments_to_utility_company = Dealership.CALCULATE(
    num_weekend_payments=COUNT(
        PaymentsMade.WHERE(
            (vendor_name == 'Utility Company') &
            (ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday')))
        )
    )
)

result = Drugs.CALCULATE(
    drug_name = drug_name,
    average_ddd = AVG(
        treatments_used_in.WHERE(HAS(end_dt)==1).CALCULATE(
            # Calculate the duration of the treatment in days
            treatment_duration_days = DATEDIFF("days", start_dt, end_dt)
            # tot_drug_amt is an original field of treatments_used_in and remains accessible
        ).WHERE(
            # Ensure the treatment duration is positive to avoid division by zero or invalid DDD
            treatment_duration_days > 0
        ).CALCULATE(
            # Calculate DDD for this specific treatment: total drug amount / duration in days
            ddd_for_this_treatment = tot_drug_amt / treatment_duration_days
        ).ddd_for_this_treatment # Extract the calculated DDD values for averaging
    )
)

patients_with_gmail_or_yahoo = Patients.WHERE(
    ENDSWITH(email, "@gmail.com") | ENDSWITH(email, "@yahoo.com")
)
result = DermTreatment.CALCULATE(
    count_patients_gmail_yahoo=COUNT(patients_with_gmail_or_yahoo)
)

result = DermTreatment.CALCULATE(
    num_patients_matching_criteria=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & (drug.drug_type == 'biologic')
                )
            ) == 1
        )
    )
)

avg_weight_for_drugalin_patients = Drugs.WHERE(drug_name == 'Drugalin').CALCULATE(
    avg_patient_weight_kg = AVG(treatments_used_in.patient.weight_kg)
)

result = DermTreatment.CALCULATE(
    caw_male_patients = AVG(Patients.WHERE(gender == 'Male').weight_kg)
)

pic_female_patients = DermTreatment.CALCULATE(
    private_insured_female_patient_count=COUNT(
        Patients.WHERE((gender == "Female") & (ins_type == "Private"))
    )
)

result = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=COUNT(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatments_used_in.start_dt)) &
            (MONTH(reported_dt) == MONTH(treatments_used_in.start_dt))
        )
    )
).TOP_K(
    1,
    by=num_adverse_events.DESC()
)

biologic_prescribing_doctors_states = Doctors.WHERE(
    HAS(prescribed_treatments.drug.WHERE(drug_type == "biologic")) == 1
).PARTITION(name="states", by=(loc_state)).CALCULATE(
    doctor_state=loc_state
)

avg_age_male_private_insurance = DermTreatment.CALCULATE(
    average_age=ROUND(
        AVG(
            Patients.WHERE(
                (gender == "Male") & (ins_type == "private")
            ).CALCULATE(
                age_in_years=DATEDIFF("years", date_of_birth, DATETIME('now'))
            ).age_in_years
        ),
        0
    )
)

active_retail_merchants_with_coupons = Merchants.WHERE(
    (status == 'active') & (LOWER(category) == 'retail') & (HAS(coupons) == 1)
).CALCULATE(
    merchant_name=name,
    total_coupons_issued=COUNT(coupons)
)

result = Users.WHERE(
    (LOWER(country) == 'us') &
    (HAS(notifications.WHERE((notification_type == 'promotional') & (status == 'unread'))) == 1)
).CALCULATE(
    username = username,
    total_unread_promotional_notifications = COUNT(
        notifications.WHERE((notification_type == 'promotional') & (status == 'unread'))
    )
)

distinct_user_ids_with_notifications = Users.WHERE(HAS(notifications)==1).CALCULATE(
    user_id=uid
)

top_merchants_by_amount = Merchants.WHERE(
    # Ensure the merchant has received transactions matching the criteria
    HAS(transactions_received.WHERE(
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150) &  # Transaction within the last 150 days
        (receiver_type == 1)  # Receiver is of type 1 (Merchant)
    )) == 1
).CALCULATE(
    merchant_name=name,
    total_transactions_count=COUNT(transactions_received.WHERE(
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150) &
        (receiver_type == 1)
    )),
    total_transaction_amount=SUM(transactions_received.WHERE(
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150) &
        (receiver_type == 1)
    ).amount)
).TOP_K(
    2,  # Select top 2 merchants
    by=total_transaction_amount.DESC()  # Order by total transaction amount descending
)

avg_session_duration_by_device_type = UserSessions.PARTITION(name="sessions_by_device_type", by=(device_type)).CALCULATE(
    device_type = device_type,
    avg_session_duration_seconds = AVG(
        DATEDIFF("seconds", UserSessions.session_start_ts, UserSessions.session_end_ts)
    )
)
